<script setup lang="ts">
import {ref, computed, onMounted, onBeforeUnmount, nextTick} from 'vue';
const art=import.meta.env.BASE_URL+'art/'; const mode=ref('anonymous'), name=ref(''); const follow=ref('no'), method=ref('LINE'), contact=ref(''); const message=ref(''), category=ref(''), trap=ref(''); const endpoint=import.meta.env.VITE_GAS_URL || 'https://script.google.com/macros/s/AKfycbx20kkUMsO6jK5CWzwqVtLqc75q_5dXUtsPAzaQ-Y-mNiDK3KWOWt0hUy41nrTOYl90/exec'; const categories=['家庭','健康','工作／學業','感情','內心平安','未來方向','其他'];
const examples = [{"tag": "日常小事", "text": "希望明天起床真的有睡飽。", "art": "character-03.webp"}, {"tag": "幽默願望", "text": "希望薪水可以跟物價一起成長。", "art": "character-11.webp"}, {"tag": "毛孩", "text": "希望我家的貓健康快樂，不要再偷吃我的早餐。", "art": "character-07.webp"}, {"tag": "學業", "text": "希望考試時，讀過的題目剛好都有出現。", "art": "character-13.webp"}, {"tag": "感情", "text": "希望下一次喜歡的人，剛好也喜歡我。", "art": "character-15.webp"}, {"tag": "家人", "text": "希望我們一家人能好好坐下來吃頓飯。", "art": "character-04.webp"}, {"tag": "內心", "text": "希望有一天，不用假裝自己過得很好。", "art": "character-02.webp"}, {"tag": "未來", "text": "希望即使還不知道方向，也有勇氣往前走。", "art": "character-17.webp"}, {"tag": "世界", "text": "希望世界少一點戰爭，多一點理解與和平。", "art": "character-18.webp"}, {"tag": "感謝", "text": "今年雖然跌跌撞撞，但謝謝自己沒有放棄。", "art": "character-05.webp"}, {"tag": "信仰", "text": "我還不認識上帝，但希望有一天能明白祂是誰。", "art": "character-14.webp"}, {"tag": "生命", "text": "希望正在接受治療的家人，有力量度過每一天。", "art": "character-04.webp"}, {"tag": "夢想", "text": "希望有一天能開一間自己的小店。", "art": "character-08.webp"}, {"tag": "生活", "text": "希望我的植物不要再被我養死了。", "art": "character-03.webp"}, {"tag": "關係", "text": "希望我能學會原諒自己，也能重新信任別人。", "art": "character-15.webp"}, {"tag": "世界", "text": "希望每個孩子都有安全的家和足夠的食物。", "art": "character-18.webp"}];
const groups=[{"tag": "生活中的小小願望", "art": "character-03.webp", "items": ["希望明天起床不要再按掉鬧鐘。", "希望今天晚上可以睡個好覺。", "希望我的植物不要再被我養死了。", "希望我的貓可以健康地陪我很久很久。"]}, {"tag": "有點幽默，但也是認真的", "art": "character-11.webp", "items": ["希望老闆突然良心發現幫我加薪。", "希望明年不要再一個人過聖誕節。", "希望減肥的毅力可以跟食慾一樣強。", "希望我的存款成長速度可以超過年齡。", "希望上班的時間可以跟放假的時間一樣快。"]}, {"tag": "正在努力的自己", "art": "character-13.webp", "items": ["希望考試順利，努力都有好的結果。", "希望有勇氣離開不適合自己的工作。", "希望找到一份喜歡又能養活自己的工作。", "希望不再那麼在意別人怎麼看我。", "希望能夠慢慢成為自己喜歡的樣子。"]}, {"tag": "那些我在乎的人", "art": "character-04.webp", "items": ["希望爸爸媽媽可以健康平安。", "希望生病的家人能夠早日康復。", "希望我和家人的關係可以慢慢變好。", "希望正在低潮的朋友能重新找回笑容。", "希望能遇見一個願意互相理解、一起成長的人。"]}, {"tag": "那些不容易說出口的心事", "art": "character-02.webp", "items": ["最近真的好累，希望能重新找回生活的力量。", "我不知道自己想要什麼，也不知道下一步該怎麼走。", "希望有一天能夠原諒自己。", "希望能慢慢走出失去重要之人的悲傷。", "希望即使現在看不到希望，也能有繼續走下去的勇氣。"]}, {"tag": "想分享的感謝與喜悅", "art": "character-05.webp", "items": ["今年終於完成了一件想做很久的事！", "謝謝這一年遇見的每一個溫暖的人。", "雖然今年不容易，但很感謝自己走到了這裡。", "希望現在擁有的幸福，也能分享給更多人。"]}, {"tag": "給這個世界的祝福", "art": "character-18.webp", "items": ["希望世界少一點戰爭，多一點理解與和平。", "希望每個孩子都能在愛與安全中長大。"]}, {"tag": "關於信仰與生命", "art": "character-14.webp", "items": ["我還不認識上帝，但想試著向祂說說話。", "希望能找到生命的意義與方向。"]}, {"tag": "RENEW｜期待一個新的開始", "art": "character-17.webp", "items": ["希望明年的新年願望，不要再跟今年一模一樣。", "希望生活少一點內耗，多一點睡眠。", "希望重新拾起那個被擱置很久的夢想。", "希望受傷的關係能有重新開始的機會。", "希望有勇氣放下過去，迎接新的可能。", "希望重新找回對生活的熱情。", "希望即使經歷過失望，仍然有相信美好的勇氣。", "希望愛能更新這個世界，讓人與人之間多一點理解與包容。"]}];
examples.push(...groups.flatMap(g=>g.items.map(text=>({tag:g.tag,art:g.art,text}))));
const index=ref(0); const example=computed(()=>examples[index.value]);
function shuffle(){index.value=(index.value+1+Math.floor(Math.random()*(examples.length-1)))%examples.length;}
const requestId=ref(crypto.randomUUID()); const submitting=ref(false);
function resetForm(){mode.value='anonymous';name.value='';follow.value='no';method.value='LINE';contact.value='';message.value='';category.value='';trap.value='';submitting.value=false;requestId.value=crypto.randomUUID();shuffle();nextTick(()=>{document.querySelectorAll('details').forEach(d=>d.open=false);window.scrollTo(0,0);});}
function restore(e:PageTransitionEvent){if(e.persisted){resetForm();}}
function submitOnce(e:Event){if(submitting.value){e.preventDefault();return;}submitting.value=true;}
onMounted(()=>{window.addEventListener('pageshow',restore);if(new URLSearchParams(location.search).has('reset')){resetForm();history.replaceState(null,'',location.pathname);}});
onBeforeUnmount(()=>window.removeEventListener('pageshow',restore));
</script>
<template><main><header>2026 耶YEAH！市集 · RENEW</header><div class="art" aria-hidden="true"><img class="mascot left" :src="art+'character-07.webp'" alt=""><img class="brand" :src="art+'character-19.webp'" alt=""><img class="mascot right" :src="art+'character-15.webp'" alt=""></div><h1>心事寄放所</h1><h2>最近，有什麼想被祝福的事嗎？</h2><p>代禱，就是讓我們透過禱告，陪伴你在意的每一件事。</p><p>不一定要是什麼了不起的大事，<br>可以是生活中的小願望、說不出口的心事，<br>也可以是正在努力的夢想。</p><p>無論你有沒有信仰，<br>無論事情有多大、多小，<br>都歡迎你在這裡留下它。💛</p><p>不用很會表達，也不用知道怎麼禱告，<br>寫下此刻心裡想到的就好。</p><section class="library"><h2>代禱範例靈感庫</h2><details v-for="g in groups" :key="g.tag"><summary><img :src="art+g.art" alt="">{{g.tag}}</summary><p v-if="g.tag.startsWith('RENEW')">如果生命中有一件事可以被更新，你希望是什麼？</p><ul><li v-for="item in g.items" :key="item">{{item}}</li></ul><p v-if="g.tag.startsWith('RENEW')">「看哪，我將一切都更新了。」—— 啟示錄 21:5</p></details></section><section class="inspiration" aria-label="代禱靈感"><h3>不知道可以寫什麼？</h3><div class="example" aria-live="polite"><img :src="art+example.art" alt=""><div><small>{{example.tag}} · 虛構範例</small><p>{{example.text}}</p></div></div><button type="button" class="shuffle" @click="shuffle">↻ 再給我一點靈感</button></section><form :action="endpoint" method="post" autocomplete="off" @submit="submitOnce"><input type="hidden" name="requestId" :value="requestId"><fieldset><legend>投稿方式</legend><label><input type="radio" name="mode" value="anonymous" v-model="mode" @change="name='';follow='no';contact=''"> 匿名</label> <label><input type="radio" name="mode" value="named" v-model="mode"> 留下姓名／暱稱</label></fieldset><template v-if="mode==='named'"><label for="name">姓名／暱稱</label><input id="name" name="name" v-model="name" required maxlength="80" autocomplete="off"><fieldset><legend>是否願意接受後續關懷？</legend><label><input type="radio" name="follow" value="no" v-model="follow" @change="contact=''"> 為我禱告就好</label><br><label><input type="radio" name="follow" value="yes" v-model="follow"> 願意接受聯繫</label></fieldset><template v-if="follow==='yes'"><label for="method">聯絡方式（擇一）</label><select id="method" name="method" v-model="method" @change="contact=''"><option>LINE</option><option>Instagram</option><option>電話</option><option>Email</option></select><label for="contact">聯絡資料</label><input id="contact" name="contact" v-model="contact" required maxlength="200" :type="method==='Email'?'email':method==='電話'?'tel':'text'"><small>同意指定同工使用此資料進行後續關懷，不用於行銷。</small></template></template><label for="category">代禱分類（選填）</label><select id="category" name="category" v-model="category"><option value="">不分類</option><option v-for="c in categories" :key="c">{{c}}</option></select><label for="message">最近，有什麼想被祝福的事呢？</label><textarea id="message" name="message" v-model="message" required maxlength="1000" rows="6" placeholder="不用想得太複雜，寫下此刻心裡想到的就好。"></textarea><small>{{message.length}} / 1000</small><div class="trap" aria-hidden="true"><input name="website" v-model="trap" tabindex="-1" autocomplete="off"></div><p class="privacy">匿名無須姓名或聯絡方式；具名可自願提供聯絡資料。內容僅供指定代禱同工閱讀，請勿在內容中填寫其他可識別個資。本服務不是即時緊急求助管道。</p><button :disabled="submitting || !message.trim() || (mode==='named' && !name.trim()) || (mode==='named' && follow==='yes' && !contact.trim()) || !endpoint">寄出我的心事 ♡</button><small v-if="!endpoint">預覽模式：尚未設定投稿服務。</small></form><footer><img class="footer-art" :src="art+'character-03.webp'" alt="">沒有太小而不值得被聆聽的心事，<br>也沒有太大而不能被禱告的事。<br><i>No prayer is too small or too big.</i><br>｜RENEW｜</footer></main></template>
<style> *{box-sizing:border-box}body{margin:0;background:#f7efd9;color:#584b38;font-family:system-ui,sans-serif}main{max-width:540px;margin:32px auto;padding:32px 24px;background:#fffdf6;border-radius:28px;box-shadow:0 12px 45px #8b74451a}header,footer,small{font-size:13px;color:#85714e}header,footer,h1,p,.art{text-align:center}.art{font-size:56px;color:#d9a642;margin:22px 0}h1{font-size:32px;margin:12px 0}p{line-height:1.9}form{display:grid;gap:12px;margin-top:28px}label{font-weight:600}select,textarea,button{font:inherit;border-radius:12px;padding:14px;border:1px solid #ded2b6;width:100%}textarea{resize:vertical;background:#fff}button{background:#f1cf74;border:0;color:#584b38;font-weight:700;cursor:pointer}button:disabled{opacity:.5;cursor:default}.privacy{font-size:13px;text-align:left}.trap{position:absolute;left:-10000px}footer{margin-top:28px}@media(max-width:560px){main{margin:12px}}.art{display:flex;align-items:center;justify-content:center;gap:6px;margin:12px 0}.brand{width:56%;object-fit:contain}.mascot{width:19%;animation:float 3s ease-in-out infinite}.right{animation-delay:-1.5s}.footer-art{display:block;width:54px;margin:0 auto 8px}@keyframes float{50%{transform:translateY(-7px)}}@media(prefers-reduced-motion:reduce){.mascot{animation:none}}body{background:#ffefac}main{background:#fffefa}button{background:#ffcf48}h1{color:#292727}fieldset{border:1px solid #ded2b6;border-radius:12px;padding:12px}input[name=name],input[name=contact]{font:inherit;padding:14px;border:1px solid #ded2b6;border-radius:12px;width:100%}h2{text-align:center;font-size:21px;color:#554329} .inspiration{background:#fff3c9;border-radius:20px;padding:16px;margin-top:22px}.inspiration h3{margin:0 0 12px;text-align:center;font-size:16px}.example{display:flex;align-items:center;gap:14px;min-height:112px}.example img{width:88px;height:88px;object-fit:contain;flex-shrink:0}.example p{text-align:left;margin:6px 0;font-weight:600;line-height:1.6}.shuffle{background:#fffefa;border:1px solid #d9bd65;margin-top:10px}.shuffle:focus-visible{outline:3px solid #3876aa;outline-offset:3px}.library details{border:1px solid #e7d8ae;border-radius:12px;margin:8px 0;padding:10px}.library summary{cursor:pointer;font-weight:600}.library summary img{width:40px;height:40px;object-fit:contain;vertical-align:middle;margin-right:8px}.library li{line-height:1.7;margin:8px 0}.library details:last-child{background:#fff1b5} 
/* Responsive layout */
main{width:calc(100% - 32px);max-width:620px;margin:24px auto;padding:clamp(18px,4vw,36px);overflow-wrap:anywhere}
h1{font-size:clamp(28px,6vw,36px)}h2{font-size:clamp(19px,4.5vw,23px)}
fieldset{min-width:0;margin:0}input,select,textarea,button{font-size:16px}button,select,input[name=name],input[name=contact]{min-height:48px}
img{max-width:100%}.example>div{min-width:0}.library summary{line-height:1.6}.library ul{padding-left:24px}
button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #3876aa;outline-offset:2px}
@media(max-width:560px){main{width:calc(100% - 24px);margin:12px auto;padding:20px 16px;border-radius:22px}.example{gap:10px}.example img{width:72px;height:72px}p{line-height:1.8}form{gap:14px}.art{gap:4px}}
@media(max-width:350px){main{width:calc(100% - 16px);padding:16px 12px}.example img{width:56px;height:56px}.library summary img{width:30px;height:30px}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;scroll-behavior:auto!important}}
</style>
